import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../../app/providers.dart';
class MajorsScreen extends ConsumerStatefulWidget {const MajorsScreen({super.key});@override ConsumerState<MajorsScreen> createState()=>_MajorsScreenState();} class _MajorsScreenState extends ConsumerState<MajorsScreen>{String _query='';@override Widget build(BuildContext context){final majors=ref.watch(majorsProvider);return Scaffold(appBar:AppBar(title:const Text('دليل التخصصات')),body:majors.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('تعذر تحميل التخصصات: $e')),data:(items){final filtered=items.where((m)=>m.name.contains(_query)||m.description.contains(_query)).toList();return ListView(padding:const EdgeInsets.all(20),children:[TextField(onChanged:(value)=>setState(()=>_query=value),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'ابحث عن تخصص')),const SizedBox(height:16),if(filtered.isEmpty)const Center(child:Padding(padding:EdgeInsets.all(32),child:Text('لا توجد تخصصات مطابقة.'))),...filtered.map((m)=>Padding(padding:const EdgeInsets.only(bottom:10),child:Card(child:ListTile(title:Text(m.name),subtitle:Text(m.description),trailing:const Icon(Icons.chevron_left),onTap:()=>showModalBottomSheet(context:context,showDragHandle:true,builder:(_)=>Padding(padding:const EdgeInsets.all(24),child:ListView(children:[Text(m.name,style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:12),Text(m.description),const SizedBox(height:12),Text('المسارات المهنية: ${m.careers.join('، ')}')]))))))]);}));}}
